  function el(tag, attrs, text) { var n = document.createElementNS(tag === 'svg' || NS_TAGS[tag] ? NS : 'http://www.w3.org/1999/xhtml', tag); for (var k in (attrs || {})) n.setAttribute(k, attrs[k]); if (text != null) n.textContent = text; return n; }
